  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary:
   * Creates a new IPO application for a retail customer.
   * The customer must provide the target company, share count greater than 0, payment amount greater than 0, and a non-null allowance document.
   * The system must verify that the customer is currently eligible for IPO and does not already have an approved application for the same company name.
   * Returns true when the application record is created successfully; otherwise false.
   * Algorithm:
   * 1. Validate input: company is non-null, shares > 0, amount > 0, doc is non-null.
   * 2. Check isEligibleForIPO().
   * 3. Search existing applications for an APPROVAL application with the same company name.
   * 4. If the customer is not eligible or already has an approved application for that company, return false.
   * 5. Create a new Application with status PENDING, provided company, shares, amount, and document.
   * 6. Link the application to this customer and add it to applications.
   * 7. Return true.
   * Related Features:
   * - canApplyForIPO
   * - email
   * - name
   * - surname
   * - telephone
   * - applications
   * - isEligibleForIPO
   * Related Classes: Application, Company, Document, ApplicationStatus
   * Input:
   * - company : Company
   *   - Target company for the IPO.
   *   - Must be non-null.
   * - shares : int
   *   - Number of shares to purchase.
   *   - Must be greater than 0.
   * - amount : double
   *   - Money amount to pay.
   *   - Must be greater than 0.
   * - doc : Document
   *   - Legal allowance documentation.
   *   - Must be non-null and must have a name identifying the document.
   * Output:
   * - boolean
   * - true if a pending application is created and added to the customer’s application list.
   * - false otherwise.
   * Pre-condition:
   * - The customer instance exists.
   * - The customer is a retail customer eligible to apply or at least potentially eligible by policy.
   * - Input parameters satisfy the required non-null and positive constraints.
   * - There is no already approved application for the same company name.
   * Post-condition:
   * - If successful, a new pending Application is stored in applications and linked to the given company, document, shares, amount, and this customer.
   * - If unsuccessful, no application is created and the customer's state remains unchanged.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public boolean createApplication(final Company company, final int shares, final double amount, final Document doc)
  {
    if (company == null || doc == null || shares <= 0 || amount <= 0)
    {
      return false;
    }

    if (!isEligibleForIPO())
    {
      return false;
    }

    final String companyName = company.getName();
    if (companyName == null)
    {
      return false;
    }

    for (Application application : getApplications())
    {
      if (application.getStatus() == ApplicationStatus.APPROVAL
          && application.getCompany() != null
          && companyName.equals(application.getCompany().getName()))
      {
        return false;
      }
    }

    Application application = IpoFactory.eINSTANCE.createApplication();
    application.setStatus(ApplicationStatus.PENDING);
    application.setCompany(company);
    application.setShare(shares);
    application.setAmountOfMoney(amount);
    application.setAllowance(doc);
    application.setCustomer(this);
    getApplications().add(application);
    return true;
    
  }

